schema_ddl:
CREATE DOMAIN importo_non_negativo AS NUMERIC(12,2) CHECK (VALUE >= 0);

CREATE DOMAIN stato_ordine AS TEXT CHECK (VALUE IN ('in_attesa', 'pagato', 'spedito', 'consegnato', 'annullato'));

CREATE TABLE clienti (
    id INT PRIMARY KEY,
    nome TEXT NOT NULL,
    cognome TEXT NOT NULL,
    email TEXT NOT NULL UNIQUE,
    data_registrazione DATE NOT NULL DEFAULT CURRENT_DATE
);

CREATE TABLE ordini (
    id INT PRIMARY KEY,
    cliente_id INT NOT NULL REFERENCES clienti(id),
    totale_ordine importo_non_negativo NOT NULL,
    stato_ordine stato_ordine NOT NULL DEFAULT 'in_attesa',
    data_ordine DATE NOT NULL DEFAULT CURRENT_DATE
);

CREATE TABLE spedizioni (
    id INT PRIMARY KEY,
    ordine_id INT NOT NULL REFERENCES ordini(id),
    corriere TEXT NOT NULL,
    costo_spedizione importo_non_negativo NOT NULL DEFAULT 0,
    data_spedizione DATE,
    data_consegna_prevista DATE,
    CHECK (data_consegna_prevista IS NULL OR data_spedizione IS NULL OR data_consegna_prevista >= data_spedizione)
);
